  "bunq-free": { zinsfreiAbStart: { url: "https://www.bunq.com/de-de/documents/personal-account-terms-conditions", stand: "23.09.2026", hinweis: "bunq-Privatkonto-AGB, Nr. 17: „Mit MassInterest kannst du Zinsen verdienen, indem du ein oder mehrere spezielle Sparkonten in der bunq-App eröffnest.“ und „Um Zinsen zu erhalten, musst du … ein Sparkonto sowie ein aktives Privat- oder Geschäftskonto (bunq Free, bunq Core, bunq Pro oder bunq Elite) haben.“ Die AGB nennen Free namentlich, Zinsen laufen nur im selbst eröffneten Sparkonto." }, keinDispoAbStart: { url: "https://www.bunq.com/de-de/documents/personal-account-terms-conditions", stand: "23.09.2026", hinweis: "bunq-Privatkonto-AGB, Nr. 25 (gelten für bunq Free, Core, Pro und Elite, also auch Free): „Normalerweise bieten wir keinen eingeräumten Dispokredit an, daher sind negative Kontostände grundsätzlich nicht erlaubt.“" }, karteOhneKredit: { url: "https://www.bunq.com/de-de/documents/personal-account-terms-conditions", stand: "26.09.2026", hinweis: "bunq-Privatkonto-AGB, Nr. 9.2: „Die digitale Kreditkarte ist mit einem separaten Zahlungskonto verknüpft, auf das du über die bunq-App oder online zugreifen kannst, und verfügt über keinen eingeräumten Dispokredit. Das bedeutet, die digitale Kreditkarte kann nur verwendet werden, wenn du ausreichendes Guthaben auf dem damit verknüpften Zahlungskonto hast.“ bunq nennt die Mastercard Kreditkarte, einen Kreditrahmen hat sie nicht. Für Free: „Wenn du ein aktives Konto hast, erhältst du eine kostenlose digitale Kreditkarte.“" } },
