  "vivid-standard": { karteOhneKredit: { url: "https://website-static.vivid.money/static/legal-docs/de-de/fee-information-document-standard.pdf", stand: "27.09.2026", hinweis: "Entgeltinformation Vivid Money S.A., Vivid Money Standard-Konto, Datum 09.09.2026: „Ausgabe einer Debitkarte“. Ersetzt am 27.09.2026 den Finanzfluss-Vergleich als Quelle." }, zinsfreiAbStart: { url: "https://support.vivid.money/en/articles/9274751-what-are-the-interest-rates-offered-by-vivid", stand: "23.09.2026", hinweis: "Vivid-Hilfe: Zinsen gibt es nur im selbst geöffneten Interest Rate Pocket. „To start earning fixed interest, just deposit funds into the 'Cash with fixed interest' section of your newly created Interest Rate Pocket.“ Der Artikel nennt Standard namentlich (Zinssatz im Pocket: 0,1 % p. a.), nichts läuft automatisch auf dem Hauptkonto." }, keinDispoAbStart: { url: "https://support.vivid.money/de/articles/8460434-warum-wird-mir-ein-negativer-saldo-angezeigt", stand: "23.09.2026", hinweis: "Vivid-Hilfe (Artikel vom 31.10.2023, gilt für alle Vivid-Konten, nennt keine Stufe): „Wir bieten keinen Dispokredit an.“ Hinweis: Eine Vorvertragsinfo von 2023 nennt zusätzlich „Vivid Now“, einen Überziehungsrahmen, den Kunden selbst beantragen müssen; ein aktuelles Angebot dazu ist nicht mehr abrufbar. Ein Dispo entsteht also höchstens auf eigenen Antrag." } },
